#!/usr/bin/env python3
"""Writes the texts of Specs/camera_rules.t27 from the readable list below.

The spec carries one generated block, between
    ; >>> generated by Specs/tables/camera_tables.py -- edit the list there, not here
    ; <<< generated
with named row indexes and the texts as packed UTF-8 bytes with offsets and lengths (t27 has no string arrays
that reach C). Run by Specs/generate.sh; edit the list here, not the spec.
"""
import pathlib
import sys

sys.dont_write_bytecode = True
from ponte_tables import table  # noqa: E402  (same folder; generate.sh runs this file directly)
from peer_tables import write_block  # noqa: E402

BEGIN = "; >>> generated by Specs/tables/camera_tables.py -- edit the list there, not here"

# The Ponte Camera extension's ID follows from the public key in camera/extension/manifest.json ("key"), so it
# is the same on every Mac: the WebSocket origin Ponte's camera link accepts. The other rows are for the tests.
EXTENSION_ID = "jinldckdcbeojhpahpkagmacfdapfnln"
ROWS = [
    ("EXTENSION_ORIGIN", f"chrome-extension://{EXTENSION_ID}"),
    ("OTHER_EXTENSION", "chrome-extension://aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"),
    ("MEET_PAGE", "https://meet.google.com"),
    ("ORIGIN_SLASH", f"chrome-extension://{EXTENSION_ID}/"),
    ("ORIGIN_UPPER", f"chrome-extension://{EXTENSION_ID.upper()}"),
]


def main():
    assert len(EXTENSION_ID) == 32 and set(EXTENSION_ID) <= set("abcdefghijklmnop"), "a Chromium extension ID"
    write_block("camera_rules.t27", table("CM_ROW", "Texts", ROWS, []), begin=BEGIN)
    print(f"camera tables: {len(ROWS)} rows")


if __name__ == "__main__":
    main()
